mapper.select:

  SELECT product_id,product_name,thumbnail_url,unit_price AS price,
  stock_available,stock_reserved,stock_sold
FROM product_inventory WHERE product_id=#{productId} AND merchant_id=#{merchantId}

mapper.update:
UPDATE product_inventory
SET merchant_id=#{merchantId},product_name=#{productName},thumbnail_url=#{thumbnailUrl},
    unit_price=#{unitPrice}
WHERE product_id=#{productId}
